import React, { useState } from 'react'
import './styles/Attendance.scss'
import AddNewPerson from '../components/AddNewPerson'
import { Toaster, toast } from 'sonner'

const Attendance = () => {
  const [isSuccessful, setSuccessful] = useState(false)
  const [fullname, setFullname] = useState('')

  const sendSonner = (firstname, lastname) => {
    toast.success(`added ${firstname} ${lastname}`)
  };

  return (
    <div className="main-container">
      <div className="attendance-container">
        <div className="home-top-container">
          <div className="section-name-container">
            <h1 className="section-name">Attendance</h1>
          </div>
            <AddNewPerson setSuccessful={ setSuccessful } setFullname={ setFullname } />
        </div>
        <div className="home-body-container">
          {isSuccessful && (
            <Toaster />
          )}
        </div>
      </div>
    </div>
  )
}

export default Attendance
